package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.graphics.drawable.ColorDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import org.json.*;

/** Every shipped theme through the real gallery, shared controls and both orientations. */
public final class TenThemeMatrixSmoke extends TenThemeSmoke {
    final List<TenThemes.Preset> presets=new ArrayList<>();final Map<String,DesktopWindow> apps=new LinkedHashMap<>();final Map<String,Integer> previewHashes=new LinkedHashMap<>();
    final StringBuilder table=new StringBuilder("Orientation\tTheme\tFinish\tApp mode\tGallery\tSwatches\tWindows\tResult\n");
    EditText note;int passed;
    @Override public void onStart(){Bundle result=new Bundle();try{
        presets.addAll(TenThemes.TEN);presets.addAll(TenThemes.AERO);store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putBoolean("weather_follow",false).putBoolean("ten_full_start",false).commit();TenThemes.TEN.get(0).apply(store);
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.find(root,DesktopIconGrid.class)!=null,"Desktop ready");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Landscape ready");
        entryPoints();fixtures();
        for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,ActivityInfo.SCREEN_ORIENTATION_PORTRAIT}){
            ui(()->home.setRequestedOrientation(orientation));await(()->(root.getWidth()>root.getHeight())==(orientation==ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE),"Theme orientation ready");SystemClock.sleep(350);
            for(int i=0;i<presets.size();i++)tryOn(presets.get(i),i,orientation);
        }
        ui(()->{home.open("setting:page:colors");check(((TenSettings)windows().get("@settings").body).page.equals("colors"),"Legacy color route opens native Colors");});
        ui(()->{TenThemes.AERO.get(2).apply(store);home.applyTenAppearance();home.open("ten-setting:colors");View tint=TenSmoke.description(root,"Aero glass tint: Ruby");check(tint!=null,"Aero tint selector is reachable");tint.performClick();check(store.prefs.getInt("aero_color",-1)==6&&store.prefs.getInt("ten_accent",0)==AeroGlass.TINTS[6],"Tint updates glass and accent together");TenThemes.AERO.get(2).apply(store);home.applyTenAppearance();check(TenThemes.currentName(store).equals("Meadow"),"Unmodified glass matches its preset");store.prefs.edit().putInt("aero_opacity",63).apply();home.applyTenAppearance();check(TenThemes.currentName(store).equals("Custom theme"),"Modified glass is identified as custom");TenThemes.AERO.get(2).apply(store);store.prefs.edit().putInt("aero_intensity",78).apply();home.applyTenAppearance();check(TenThemes.currentName(store).equals("Custom theme"),"Modified intensity is identified as custom");});shot("ten6-aero-colors");
        ui(()->{TenThemes.TEN.get(0).apply(store);home.applyTenAppearance();home.open("ten-setting:themes");});saveTable();
        result.putString("stream","PASS: all 17 themes applied through gallery in portrait and landscape (34 combinations), 12 built-in windows, preserved note/selection and instances, shell surfaces, accurate independent previews, eight literal glass swatches, legacy/desktop Personalize routes, tint controls and custom-theme identity\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){try{saveTable();shot("ten6-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
    void entryPoints()throws Exception{
        ui(()->{try{Method menu=MainActivity.class.getDeclaredMethod("desktopOptions",float.class,float.class);menu.setAccessible(true);menu.invoke(home,70f,70f);}catch(Exception e){throw new RuntimeException(e);}});systemClick("Personalize");await(()->windows().containsKey("@settings")&&windows().get("@settings").body instanceof TenSettings,"Desktop Personalize opens Settings");ui(()->{check(((TenSettings)windows().get("@settings").body).page.equals("themes"),"Desktop menu opens Themes, not Seven personalization");check(count(TenSmoke.find(root,TenThemeGallery.class),"Apply theme:")==17,"All themes are discoverable from the desktop menu");home.open("setting:page:personalization");check(((TenSettings)windows().get("@settings").body).page.equals("themes"),"Legacy personalization route opens Themes");home.open("@legacycontrol");VistaControlPanel panel=(VistaControlPanel)windows().get("@legacycontrol").body;panel.navigate("personalization");check(count(panel,"Apply theme:")==17,"Restored legacy page also lists Ten and Aero themes");panel.navigate("colors");check(TenSmoke.find(panel,TenAeroColors.class)!=null,"Legacy glass controls use the literal picker");windows().get("@legacycontrol").closeWindow();});shot("ten6-theme-entry");
    }
    void fixtures()throws Exception{ui(()->{for(String id:new String[]{"@notes","@files","@calendar","@browser","@nota","@taskmanager","@recycle","@sticky","@photos","@weather","@gadget:calculator","@settings"}){home.open(id);DesktopWindow window=windows().get(id);check(window!=null&&window.getParent()!=null,"Built-in window opens: "+id);apps.put(id,window);}note=(EditText)TenSmoke.description(apps.get("@notes"),"Notepad text");note.setText("All seventeen themes keep this document and selection.");note.setSelection(4,13);((TenSettings)apps.get("@settings").body).navigate("themes");});}
    void tryOn(TenThemes.Preset theme,int index,int orientation)throws Exception{
        ui(()->{home.open("ten-setting:themes");TenThemeGallery gallery=TenSmoke.find(apps.get("@settings").body,TenThemeGallery.class);View card=TenSmoke.description(gallery,"Apply theme: "+theme.name);check(card!=null,"Theme exists: "+theme.name);card.performClick();check(theme.matches(store)&&TenThemes.currentName(store).equals(theme.name),"Preset fully applied: "+theme.name);check(store.prefs.getInt("wallpaper",-1)==theme.wallpaper,"Wallpaper applied");check(TenThemes.aero(store.prefs)==theme.aero&&TenAppearance.dark(home)==theme.appsDark(),"Finish and application mode applied");TenThemeGallery fresh=TenSmoke.find(apps.get("@settings").body,TenThemeGallery.class);check(count(fresh,"Apply theme:")==17&&selected(fresh)==1,"Full gallery retains exactly one selection");
            for(Map.Entry<String,DesktopWindow> entry:apps.entrySet()){DesktopWindow window=entry.getValue();check(windows().get(entry.getKey())==window,"Existing instance retained");check(window.body.getBackground() instanceof ColorDrawable,"Native root surface");double luma=TenAppearance.luma(((ColorDrawable)window.body.getBackground()).getColor());check(theme.appsDark()?luma<75:luma>200,"Application surface follows "+theme.name+": "+entry.getKey());}
            check(note.getText().toString().equals("All seventeen themes keep this document and selection.")&&note.getSelectionStart()==4&&note.getSelectionEnd()==13,"Note and selection retained");check(theme.appsDark()?TenAppearance.luma(note.getCurrentTextColor())>200:TenAppearance.luma(note.getCurrentTextColor())<90,"Note foreground contrast");
            TenSettings settings=(TenSettings)apps.get("@settings").body;TextView selected=(TextView)TenSmoke.description(settings.side,"Themes");android.graphics.drawable.LayerDrawable selectedBackground=(android.graphics.drawable.LayerDrawable)selected.getBackground();int fill=((ColorDrawable)selectedBackground.getDrawable(0)).getColor();check(TenAppearance.contrast(selected.getCurrentTextColor(),fill)>=4.5,"Selected Settings label stays readable: "+theme.name);
            swatches();previews(fresh);((TenSettings)apps.get("@settings").body).scroll.scrollTo(0,0);TenSmoke.description(root,"Start menu").performClick();
        });waitForIdleSync();
        ui(()->{StartMenu start=TenSmoke.find(root,StartMenu.class);check(start.getVisibility()==View.VISIBLE&&start.getBackground() instanceof AeroGlass,"Start retains live shell finish");check(TenSmoke.description(root,"Desktop taskbar").getBackground() instanceof AeroGlass,"Taskbar retains live shell finish");if(orientation==ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE)report(theme,index,start);start.hide();});
        passed++;table.append(orientation==ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE?"Landscape":"Portrait").append('\t').append(theme.name).append('\t').append(theme.aero?"Aero":"Ten").append('\t').append(theme.appsDark()?"Dark":"Light").append("\t17\t8\t12\tPASS\n");saveTable();
    }
    int selected(View view){int n=view.isSelected()&&view.getContentDescription()!=null&&view.getContentDescription().toString().startsWith("Apply theme:")?1:0;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)n+=selected(((ViewGroup)view).getChildAt(i));return n;}
    void swatches(){TenAeroColors palette=new TenAeroColors(home,store,()->{});TenAppearance.apply(palette);int width=Aero.dp(home,320);palette.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));palette.layout(0,0,width,palette.getMeasuredHeight());Set<Integer> colors=new HashSet<>();for(int i=0;i<AeroGlass.TINTS.length;i++){View sample=TenSmoke.description(palette,"Aero tint sample: "+AeroGlass.COLOR_NAMES[i]);Bitmap bitmap=Bitmap.createBitmap(sample.getWidth(),sample.getHeight(),Bitmap.Config.ARGB_8888);sample.draw(new Canvas(bitmap));int center=bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2);check(distance(center,AeroGlass.TINTS[i])<5,"Swatch shows its actual tint: "+AeroGlass.COLOR_NAMES[i]);colors.add(center);bitmap.recycle();}check(colors.size()==8,"All eight tint samples remain distinct");}
    void previews(TenThemeGallery gallery){for(TenThemes.Preset preset:presets){View sample=TenSmoke.description(gallery,"Theme appearance sample: "+preset.name);sample.measure(View.MeasureSpec.makeMeasureSpec(240,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(140,View.MeasureSpec.EXACTLY));sample.layout(0,0,240,140);Bitmap image=Bitmap.createBitmap(240,140,Bitmap.Config.ARGB_8888);sample.draw(new Canvas(image));int[] pixels=new int[240*140];image.getPixels(pixels,0,240,0,0,240,140);int hash=Arrays.hashCode(pixels);Integer prior=previewHashes.putIfAbsent(preset.name,hash);check(prior==null||prior==hash,"Theme preview is independent of the applied theme: "+preset.name);image.recycle();}}
    int distance(int a,int b){return Math.abs(Color.red(a)-Color.red(b))+Math.abs(Color.green(a)-Color.green(b))+Math.abs(Color.blue(a)-Color.blue(b));}
    void report(TenThemes.Preset theme,int index,StartMenu start){Bitmap image=Bitmap.createBitmap(1500,1040,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(0xff3a3a3a);Paint paint=new Paint(3);paint.setColor(Color.WHITE);paint.setTextSize(25);canvas.drawText(theme.name+" · "+(theme.aero?"Aero":"Ten")+" · "+(theme.appsDark()?"Dark apps":"Light apps"),20,34,paint);View bar=TenSmoke.description(root,"Desktop taskbar");paintView(canvas,bar,20,52,1460,78);paintView(canvas,apps.get("@notes"),20,160,710,400);paintView(canvas,apps.get("@files"),770,160,710,400);paintView(canvas,apps.get("@settings"),20,600,710,410);paintView(canvas,start,770,600,710,410);try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),String.format(Locale.ROOT,"ten6-theme-%02d.png",index)))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}finally{image.recycle();}}
    void paintView(Canvas canvas,View view,int x,int y,int width,int height){if(view.getWidth()<1||view.getHeight()<1)return;float scale=Math.min(width/(float)view.getWidth(),height/(float)view.getHeight());int saved=canvas.save();canvas.translate(x,y);canvas.scale(scale,scale);if(view instanceof DesktopWindow)((DesktopWindow)view).drawPreview(canvas);else view.draw(canvas);canvas.restoreToCount(saved);}
    void saveTable()throws IOException{try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(getTargetContext().getFilesDir(),"ten6-theme-matrix.tsv")),java.nio.charset.StandardCharsets.UTF_8)){out.write(table.toString());}}
}
